func GitCheckout(t *testing.T, repoDir, branchName string) {
	t.Helper()
	cmd := exec.Command("git", "checkout", branchName)
	cmd.Dir = repoDir
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git checkout %s failed: %v\n%s", branchName, err, string(out))
	}
}

